import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.DCk0k6gb.js";const k=JSON.parse('{"title":"Migrate to 0.2.0","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration-0.2.md","filePath":"guide/migration-0.2.md"}'),o={name:"guide/migration-0.2.md"};function n(r,e,d,l,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="migrate-to-0-2-0" tabindex="-1">Migrate to 0.2.0 <a class="header-anchor" href="#migrate-to-0-2-0" aria-label="Permalink to &quot;Migrate to 0.2.0&quot;">​</a></h1><p><a href="/sa-token-rust/zh/guide/migration-0.2.html">中文</a></p><p>Use this page when upgrading from 0.1.x to 0.2.0. The full bilingual document also lives at the repository root: <a href="https://github.com/sa-tokens/sa-token-rust/blob/main/MIGRATION_0.2.md" target="_blank" rel="noreferrer">MIGRATION_0.2.md</a>.</p><p>Design is inspired by Dromara sa-token; this tree is an independent implementation (MIT OR Apache-2.0). See <code>NOTICE</code>.</p><h2 id="behaviour-that-can-silently-change-production" tabindex="-1">Behaviour that can silently change production <a class="header-anchor" href="#behaviour-that-can-silently-change-production" aria-label="Permalink to &quot;Behaviour that can silently change production&quot;">​</a></h2><h3 id="auto-renew-defaults-to-false" tabindex="-1"><code>auto_renew</code> defaults to <code>false</code> <a class="header-anchor" href="#auto-renew-defaults-to-false" aria-label="Permalink to &quot;`auto_renew` defaults to `false`&quot;">​</a></h3><p>In 0.1.x a token read could rewrite TTL. Since 0.2.0 the default is off to avoid a storage write on every read. Opt in only if you need the old behaviour:</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaTokenConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(storage)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auto_renew</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">renew_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">try_build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="is-read-actually-applies" tabindex="-1"><code>is_read_*</code> actually applies <a class="header-anchor" href="#is-read-actually-applies" aria-label="Permalink to &quot;`is_read_*` actually applies&quot;">​</a></h3><p><code>is_read_header</code> / <code>is_read_cookie</code> / <code>is_read_body</code> control extraction through <code>token_io::read_token</code>. Do not disable <code>is_read_header</code> if clients send the token in a header.</p><h3 id="jwt" tabindex="-1">JWT <a class="header-anchor" href="#jwt" aria-label="Permalink to &quot;JWT&quot;">​</a></h3><ul><li>Missing / empty <code>jwt_secret_key</code> with <code>TokenStyle::Jwt</code> → <code>Err(SaTokenError::ConfigError)</code> from <code>try_build</code> / <code>TokenGenerator</code> (no library-path panic).</li><li><code>jwt_fallback_on_error</code> defaults to <code>false</code>. A failed JWT no longer silently becomes a UUID.</li></ul><h3 id="sa-ignore-does-not-skip-middleware" tabindex="-1"><code>#[sa_ignore]</code> does not skip middleware <a class="header-anchor" href="#sa-ignore-does-not-skip-middleware" aria-label="Permalink to &quot;`#[sa_ignore]` does not skip middleware&quot;">​</a></h3><p>Public routes must be listed in <code>PathAuthConfig::exclude</code>. The attribute only skips the macro-inserted check; it does not bypass Layer / Middleware.</p><h3 id="online-users-are-presence" tabindex="-1">Online users are presence <a class="header-anchor" href="#online-users-are-presence" aria-label="Permalink to &quot;Online users are presence&quot;">​</a></h3><p><code>OnlineManager::new()</code> stays process-local. Cross-instance presence requires <code>with_distributed_online()</code>. HTTP login does not call <code>mark_online</code>.</p><h3 id="token-prefix-exists" tabindex="-1"><code>token_prefix</code> (exists) <a class="header-anchor" href="#token-prefix-exists" aria-label="Permalink to &quot;`token_prefix` (exists)&quot;">​</a></h3><p>Optional config: <code>.token_prefix(&quot;Bearer &quot;)</code>.</p><ul><li>Applied by <code>token_io::apply_token_prefix</code> when reading tokens.</li><li><code>None</code> (default) still strips a leading <code>Bearer </code>.</li><li>Empty string is rejected at <code>try_build</code> time.</li></ul><p>The token <strong>key name</strong> remains <code>token_name</code> (default <code>&quot;sa-token&quot;</code>). Do not confuse name and prefix.</p><h3 id="cookie-writes-is-write-cookie-exists" tabindex="-1">Cookie writes: <code>is_write_cookie</code> (exists) <a class="header-anchor" href="#cookie-writes-is-write-cookie-exists" aria-label="Permalink to &quot;Cookie writes: `is_write_cookie` (exists)&quot;">​</a></h3><p>Login does not automatically <code>Set-Cookie</code>. To emit cookies:</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaTokenConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(storage)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is_write_cookie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cookie_http_only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">try_build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Call <code>write_token_cookie</code> on the response path; use <code>delete_token_cookie</code> on logout. When the flag is <code>false</code> (default), both helpers are no-ops.</p><h3 id="pluggable-storage-encoding-saserializer" tabindex="-1">Pluggable storage encoding (<code>SaSerializer</code>) <a class="header-anchor" href="#pluggable-storage-encoding-saserializer" aria-label="Permalink to &quot;Pluggable storage encoding (`SaSerializer`)&quot;">​</a></h3><p>Storage payloads (token info, sessions, nonce, OAuth2/SSO, …) go through <code>SaTokenConfig.serializer</code> (<code>SharedSerializer</code>). Default is JSON. Optional binary encoding needs Cargo feature <code>fory</code> and <code>.serializer(SharedSerializer::from(ForySerializer::default()))</code>. Fory can still <strong>read</strong> legacy pure JSON (rolling upgrade); switching writers back to JSON while binary rows remain will fail with a format mismatch. Full guide: <a href="./storage.html">Storage</a>.</p><h2 id="removed-items-and-replacements" tabindex="-1">Removed items and replacements <a class="header-anchor" href="#removed-items-and-replacements" aria-label="Permalink to &quot;Removed items and replacements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Removed / deprecated</th><th>Replacement</th></tr></thead><tbody><tr><td><code>SaStorage::keys</code></td><td><code>SaStorage::scan</code> until <code>next_cursor == 0</code></td></tr><tr><td>Direct <code>SaStorage</code> in services</td><td><code>SaTokenDao</code> (<code>set_object</code> / <code>get_object</code> / <code>cas</code> / <code>list_*</code>)</td></tr><tr><td><code>sa-token-plugin-*-core</code></td><td><code>sa-token-plugin-common</code> (<code>SaTokenState</code>)</td></tr><tr><td><code>FrameworkAdapter</code></td><td><code>sa_token_adapter::plugin::SaTokenPlugin</code></td></tr><tr><td><code>init_manager</code> as happy path</td><td><code>try_init_manager</code> → <code>Result</code></td></tr><tr><td><code>put_stp_logic</code> / global registry</td><td><strong>Deprecated no-ops</strong> — use <code>SaLogic::new</code> / <code>StpUtil::stp_logic</code> (cheap Clone façade; no registry)</td></tr><tr><td>Process-local OAuth2/SSO <code>HashMap</code></td><td>Dao-backed stores</td></tr></tbody></table><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0.1.x</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// use sa_token_plugin_axum_core::SaTokenState;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0.2.0</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sa_token_plugin_common</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SaTokenState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or: use sa_token_plugin_axum::*;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="signatures-and-modules" tabindex="-1">Signatures and modules <a class="header-anchor" href="#signatures-and-modules" aria-label="Permalink to &quot;Signatures and modules&quot;">​</a></h2><p>Prefer <code>try_build</code> / <code>try_init_manager</code> / <code>try_get_manager</code>. Adapters should read tokens with <code>token_io::read_token</code>. Login and grants go through <code>AuthService</code> / <code>AuthzService</code>. Multi-account uses <code>login_type</code> + <code>SaLogic</code>. <code>StpUtil::login</code> always uses default <code>login_type</code>; use <code>login_with_type</code> / <code>TokenBuilder</code> / <code>SaLogic</code> for others.</p><p>Real new paths include: <code>dao.rs</code>, <code>keys.rs</code>, <code>token_io.rs</code>, <code>codec.rs</code>, <code>service/</code>, <code>stp_logic.rs</code>, <code>oauth2/</code>, <code>sso/</code>, <code>cleanup/</code>, and <code>sa-token-plugin-common</code>. Adapter adds <code>SaSerializer</code> / <code>SharedSerializer</code>. Dao has <strong>no</strong> <code>set_json</code>; configuration errors use <code>ConfigError</code>.</p><h2 id="storage-capability-short" tabindex="-1">Storage capability (short) <a class="header-anchor" href="#storage-capability-short" aria-label="Permalink to &quot;Storage capability (short)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Memory</th><th>Redis</th><th>Database</th></tr></thead><tbody><tr><td>Basic KV</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>get_del</code> / CAS / list / <code>scan</code></td><td>yes</td><td>yes</td><td><strong>Unsupported</strong></td></tr></tbody></table><p>Do not rely on the database backend for nonce one-shot consume, online indexes, or multi-device lists yet.</p><h2 id="upgrade-checklist" tabindex="-1">Upgrade checklist <a class="header-anchor" href="#upgrade-checklist" aria-label="Permalink to &quot;Upgrade checklist&quot;">​</a></h2><ol><li>Bump every <code>sa-token-*</code> dependency to <code>0.2.0</code>.</li><li>Replace <code>*-core</code> imports with <code>sa-token-plugin-common</code> / the plugin prelude.</li><li>Switch <code>init_manager</code> → <code>try_init_manager</code>; use <code>try_build</code> in libraries.</li><li>Handle <code>Result</code> from token generation, online users, and JWT.</li><li>Set <code>auto_renew(true)</code> only if you need 0.1.x renewal.</li><li>Move public routes to <code>PathAuthConfig::exclude</code>.</li><li>Configure <code>token_prefix</code> / <code>is_write_cookie</code> when needed.</li><li>Re-read OAuth2 (hashed secrets, PKCE) and SSO ticket consume.</li><li>Replace <code>put_stp_logic</code> with <code>SaLogic::new</code> / <code>StpUtil::stp_logic</code> (registry is gone; old APIs are no-ops).</li><li>If you need non-JSON storage encoding, enable <code>fory</code> and set <code>.serializer(...)</code> — see <a href="/sa-token-rust/guide/storage.html">Storage</a>.</li><li>Run <code>cargo check --workspace</code>, then <code>cargo clippy --workspace --lib</code>.</li></ol><h2 id="related-links" tabindex="-1">Related links <a class="header-anchor" href="#related-links" aria-label="Permalink to &quot;Related links&quot;">​</a></h2><ul><li><a href="/sa-token-rust/guide/quick-start.html">Quick start</a></li><li><a href="/sa-token-rust/guide/path-auth.html">Path auth</a></li><li><a href="/sa-token-rust/guide/storage.html">Storage</a></li><li><a href="/sa-token-rust/reference/error-reference.html">Error reference</a></li><li>Issues: <a href="https://github.com/sa-tokens/sa-token-rust/issues" target="_blank" rel="noreferrer">https://github.com/sa-tokens/sa-token-rust/issues</a></li></ul>',39)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
